/** Responsive image sources generated by scripts/optimize-images.mjs. Keep in sync with image-manifest.json. */
type ImageSet = { widths: number[]; width: number; height: number; fallback: 'jpg' | 'png' };

export const images: Record<string, ImageSet> = {
  'researcher-cabinet': { widths: [640, 960, 1280], width: 1280, height: 960, fallback: 'jpg' },
  'researcher-cabinet-mobile': { widths: [480, 780], width: 780, height: 780, fallback: 'jpg' },
  'research-team': { widths: [720, 1080, 1600], width: 1600, height: 2133, fallback: 'jpg' },
  'cell-culture-plate': { widths: [480, 800, 1200], width: 1200, height: 900, fallback: 'jpg' },
  'media-preparation': { widths: [400, 576], width: 576, height: 704, fallback: 'jpg' },
  'clearx9-media': { widths: [584], width: 584, height: 276, fallback: 'png' },
};

export function srcSet(id: string, format: string) {
  const set = images[id];
  return set.widths.map((w) => `/images/photos/${id}-${w}.${format} ${w}w`).join(', ');
}

export function fallbackSrc(id: string) {
  const set = images[id];
  return `/images/photos/${id}-${set.widths[set.widths.length - 1]}.${set.fallback}`;
}
